import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String str = scanner.next();
        char first_char = str.charAt(0);
        str = str.substring(1);
        int at_position = str.indexOf("at");
        if (at_position != -1) {
            str = str.substring(0, at_position) + "@" + str.substring(at_position + 2);
        }
        int dot_position;
        while ((dot_position = str.indexOf("dot")) != -1 && dot_position != str.length() - 3) {
            str = str.substring(0, dot_position) + "." + str.substring(dot_position + 3);
        }
        System.out.println(first_char + str);
        scanner.close();
    }
}
